import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            K = int(next(iterator))
            S = next(iterator)
        except StopIteration:
            break

        sorted_s = ''.join(sorted(S))
        results.append(sorted_s)

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
